import { useState, useRef, useEffect, useContext } from "react";
import AddEpenseFormComponent from "./AddExpenseForm";
import { deleteExpenseData } from "../service/firebaseService";
import database from "../firebase";
import DataContext from "../context/dataContext";
import { Table, Thead, Tbody, Tr, Th, Td } from "react-super-responsive-table";
import "react-super-responsive-table/dist/SuperResponsiveTableStyle.css";
function ExpenseList() {
  const { expenseData } = useContext(DataContext);
  //const [expenseData, setExpenseData] = useState([]);
  const childRef = useRef(null);

  const [selectedData, setSelectedData] = useState({});

  const addExpense = (data) => {

    if (data.name && childRef.current) {
      childRef.current.setIsExpenseTypeForm(false);
      childRef.current.setFormData(data);
      childRef.current.setIsAdd(false);
      childRef.current && childRef.current.handleShow();
    } else {
      childRef.current.setIsExpenseTypeForm(false);
      childRef.current.setFormData({});
      childRef.current.setIsAdd(true);
      childRef.current && childRef.current.handleShow();
    }
  };

  const removeExpenseData = (data) => {
    if (window.confirm('Do you want to delete the expense data?')) {
      deleteExpenseData("expenses", data.id);
    } else {
console.log("not deleted")
    }

  };

  const calculateTotalExpense = () => {
    let sum = 0;
    expenseData &&
      expenseData.length &&
      expenseData.map((data) => {
        sum = sum + parseFloat(data.price);
      });
    return sum;
  };

  const generateTableRows = (expenseData) => {
    return (
      expenseData &&
      expenseData.length &&
      expenseData.map((data) => {
        return (
          <Tr className="bg-light border border-dark">
            <Td>{data.name}</Td>
            <Td> {data.type}</Td>
            <Td>{data.date}</Td>
            <Td> {data.price}</Td>
            <Td>
              <div>
                <button
                  type="button"
                  class="btn btn-danger p-1"
                  onClick={(e) => {
                    removeExpenseData(data);
                  }}
                >
                  <i class="bi bi-trash"></i>
                </button>
                <span className="p-2">
                  <button
                    type="button"
                    onClick={(e) => {
                      addExpense(data);
                    }}
                    class="btn btn-primary p-1"
                  >
                    <i class="bi bi-pencil-fill"></i>
                  </button>
                </span>
              </div>
            </Td>
          </Tr>
        );
      })
    );
  };
  return (
    <div className="container">
      <AddEpenseFormComponent
        ref={childRef}
        editData={selectedData || {}}
        dataCount={expenseData ? expenseData.length : 0}
      ></AddEpenseFormComponent>
      <div className="card">
        <div className="card-body">
          <div>
            <button
              type="button"
              onClick={addExpense}
              className="btn btn-success p-1 float-start"
            >
              Add Expense
              <i class="bi bi-plus-circle p-1"></i>
            </button>
          </div>
          <div className="float-end badge bg-info text-dark p-2 me-3">
            Total: {calculateTotalExpense()}
          </div>
        </div>
      </div>
      <div className="card">
        <div className="card-body">
          <Table>
            <Thead>
              <Tr className="bg-secondary border border-dark">
                <Th>Expense Name</Th>
                <Th>Expense Type</Th>
                <Th>Expense Date</Th>
                <Th>Expense Amount</Th>
                <Th>Actions</Th>
              </Tr>
            </Thead>
            <Tbody>{generateTableRows(expenseData)}</Tbody>
          </Table>
        </div>
      </div>
    </div>
  );
}

export default ExpenseList;
